import anchorsJson from './face-anchors.json';
import stampsJson from './face-stamps.json';
import { bodyUrl, type Frame } from './paperDoll';

// Generated by apps/cheliki/scripts/doll: face-stamps.json by export_stamps.py from stamps.py,
// face-anchors.json by face_anchors.py and then aseprite_sync.py anchors.

export type Eyes = keyof typeof stampsJson.eyes;
export type Brows = keyof typeof stampsJson.brows;
export type Mouth = keyof typeof stampsJson.mouths;
export const EYES = Object.keys(stampsJson.eyes) as Eyes[];
export const BROWS = Object.keys(stampsJson.brows) as Brows[];
export const MOUTHS = Object.keys(stampsJson.mouths) as Mouth[];

export interface Face {
  eyes: Eyes;
  brows: Brows;
  mouth: Mouth;
}

/** Eyes open, half-closed, closed. */
export type BlinkState = 0 | 1 | 2;

/** [x, y] in the frame canvas. */
type Point = number[];
interface Anchors {
  /** Two for a front or three-quarter face, one for a profile. */
  eyes: Point[];
  mouth: Point;
}
const ANCHORS: Record<string, Anchors> = anchorsJson;

/** A stamp pixel: offset from its anchor and RGB. */
interface Pixel {
  dx: number;
  dy: number;
  rgb: [number, number, number];
}
/** [dx, dy, '#rrggbb'] as exported. */
type RawPixel = (number | string)[];

function pixels(raw: RawPixel[]): Pixel[] {
  return raw.map(([dx, dy, hex]) => {
    const n = parseInt(String(hex).slice(1), 16);
    return { dx: Number(dx), dy: Number(dy), rgb: [n >> 16, (n >> 8) & 255, n & 255] };
  });
}

/** Eyes and brows: a front pair hanging off the two eye anchors, or one profile feature. */
interface PairStamp {
  left: Pixel[];
  right: Pixel[];
  profile: Pixel[];
}
interface MouthStamp {
  front: Pixel[];
  profile: Pixel[];
}

type RawPair = { front: { left: RawPixel[]; right: RawPixel[] }; profile: RawPixel[] };
const pair = ({ front, profile }: RawPair): PairStamp => ({
  left: pixels(front.left),
  right: pixels(front.right),
  profile: pixels(profile),
});

const mapValues = <T, R>(record: Record<string, T>, fn: (value: T) => R) => (
  Object.fromEntries(Object.entries(record).map(([key, value]) => [key, fn(value)]))
);

const STAMPS = {
  /** By blink state. */
  eyes: mapValues(stampsJson.eyes, states => states.map(pair)) as Record<Eyes, PairStamp[]>,
  brows: mapValues(stampsJson.brows, pair) as Record<Brows, PairStamp>,
  mouths: mapValues(stampsJson.mouths, m => ({
    front: pixels(m.front),
    profile: pixels(m.profile),
  })) as Record<Mouth, MouthStamp>,
};

/** Darker body pixels are the outline: the face never draws on them. */
const OUTLINE = 60;

/**
 * Draws stamp pixels at the anchor into `out`, only where `body` has skin. A west profile is the
 * east one mirrored about the anchor.
 */
function draw(out: ImageData, body: ImageData, px: Pixel[], anchor: Point, mirrored = false) {
  const { width, height, data } = body;
  const [ax = 0, ay = 0] = anchor;
  for (const { dx, dy, rgb } of px) {
    const x = mirrored ? ax + 1 - dx : ax + dx;
    const y = ay + dy;
    if (x < 0 || y < 0 || x >= width || y >= height) continue;
    const i = (y * width + x) * 4;
    if (!data[i + 3] || (data[i]! + data[i + 1]! + data[i + 2]!) / 3 < OUTLINE) continue;
    out.data.set(rgb, i);
  }
}

/** The body frame with the face stamped on it. */
export function withFace(body: ImageData, frame: Frame, face: Face, blink: BlinkState): ImageData {
  const anchors = ANCHORS[frame.src];
  const out = new ImageData(new Uint8ClampedArray(body.data), body.width, body.height);
  if (!anchors) return out;
  const parts = [STAMPS.brows[face.brows], STAMPS.eyes[face.eyes][blink]!];
  const [left, right] = anchors.eyes;
  if (left && right) {
    for (const part of parts) {
      draw(out, body, part.left, left);
      draw(out, body, part.right, right);
    }
    draw(out, body, STAMPS.mouths[face.mouth].front, anchors.mouth);
  } else if (left) {
    const mirrored = frame.facing === 'west';
    for (const part of parts) draw(out, body, part.profile, left, mirrored);
    draw(out, body, STAMPS.mouths[face.mouth].profile, anchors.mouth, mirrored);
  }
  return out;
}

const bodies = new Map<string, Promise<ImageData>>();

/** The body frame's pixels, loaded once. */
export function loadBody(frame: Frame): Promise<ImageData> {
  let body = bodies.get(frame.src);
  if (!body) {
    body = new Promise<ImageData>((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
        ctx.drawImage(img, 0, 0);
        resolve(ctx.getImageData(0, 0, img.width, img.height));
      };
      img.onerror = () => reject(new Error(`Can't load ${img.src}`));
      img.src = bodyUrl(frame);
    });
    bodies.set(frame.src, body);
  }
  return body;
}
